def click_with_retry(driver, xpaths, timeout=10, retry=3):
    for _ in range(retry):
        remove_masks(driver)
        for xp in xpaths:
            try:
                WebDriverWait(driver, timeout).until(
                    lambda d: len(d.find_elements(By.XPATH, xp)) > 0
                )
                elements = driver.find_elements(By.XPATH, xp)

                target = None
                for el in elements:
                    try:
                        if el.is_displayed():
                            target = el
                            break
                    except:
                        continue

                if target is None and elements:
                    target = elements[0]

                if target is None:
                    continue

                driver.execute_script("arguments[0].scrollIntoView({block:'center'});", target)
                time.sleep(0.4)

                try:
                    target.click()
                except:
                    driver.execute_script("arguments[0].click();", target)

                time.sleep(1)
                return True
            except:
                continue
        time.sleep(1)
    return False


def parse_float(text):
    if text is None:
        return None
    s = str(text).strip().replace(",", "").replace("\t", " ").replace(" ", "")
    if not s or s == "-":
        return None
    m = re.search(r"[+-]?\d+(?:\.\d+)?", s)
    if not m:
        return None
    try:
        return float(m.group())
    except:
        return None


def sign_diff(diff, ma):
    if ma in (None, 0):
        return 0
    if abs(diff) / ma <= 0.003:
        return 0
    return 1 if diff > 0 else -1


