def detect_market(stockID: str):
    if stockID.startswith(("600", "601", "603", "605", "688", "689")):
        return 1
    elif stockID.startswith(("000", "001", "002", "003", "300", "301")):
        return 0
    else:
        raise ValueError(f"无法判断交易所，请手动确认股票代码: {stockID}")


def load_stock_list(file_path):
    stock_list = []
    seen = set()

    if not os.path.exists(file_path):
        raise FileNotFoundError(f"股票列表文件不存在: {file_path}")

    with open(file_path, "r", encoding="utf-8") as f:
        for line in f:
            code = line.strip()
            if code and code.isdigit() and code not in seen:
                stock_list.append(code)
                seen.add(code)
    return stock_list


def get_stock_name(driver, stockID):
    xpaths = [
        "/html/body/div[1]/div/div[3]/div[1]/div[1]/span[1]",
        "//span[contains(@class,'name')]",
        "//h1",
        "//title",
    ]

    for xp in xpaths:
        try:
            els = driver.find_elements(By.XPATH, xp)
            for el in els:
                txt = el.text.strip()
                if txt and txt != "-":
                    cleaned = (
                        txt.replace(stockID, "")
                        .replace("(", "")
                        .replace(")", "")
                        .replace("（", "")
                        .replace("）", "")
                        .strip()
                    )
                    cleaned = normalize_space(cleaned)
                    if cleaned:
                        return cleaned
        except:
            continue

    return f"unknown_stock_{stockID}"


