def extract_basic_info_structured(driver):
    result = {
        "close": None,
        "change_pct": None,
        "open": None,
        "prev_close": None,
        "high": None,
        "low": None,
        "turnover_rate": None,
        "volume_ratio": None,
        "volume": None,
        "amount": None,
    }

    close_xps = [
        "/html/body/div[1]/div/div[3]/div[2]/div[1]/div[1]/span[1]/span",
        "//div[contains(@class,'price')]//span",
    ]
    pct_xps = [
        "/html/body/div[1]/div/div[3]/div[2]/div[1]/div[2]/span[1]/span/span",
        "//span[contains(text(),'%')]",
    ]

    for xp in close_xps:
        try:
            el = driver.find_element(By.XPATH, xp)
            result["close"] = parse_float(el.text.strip())
            if result["close"] is not None:
                break
        except:
            continue

    for xp in pct_xps:
        try:
            el = driver.find_element(By.XPATH, xp)
            result["change_pct"] = parse_float(el.text.strip())
            if result["change_pct"] is not None:
                break
        except:
            continue

    panel_candidates = [
        "/html/body/div[1]/div/div[3]/div[2]/div[2]",
        "//*[contains(text(),'今开') and contains(text(),'昨收')]",
        "//*[contains(text(),'换手率') and contains(text(),'量比')]",
    ]

    panel_text = ""
    for xp in panel_candidates:
        try:
            el = driver.find_element(By.XPATH, xp)
            txt = el.text.strip()
            if txt:
                panel_text = txt
                break
        except:
            continue

    if panel_text:
        pairs = {
            "open": r"今开[:：]?\s*([0-9.\-]+)",
            "prev_close": r"昨收[:：]?\s*([0-9.\-]+)",
            "high": r"最高价[:：]?\s*([0-9.\-]+)",
            "low": r"最低价[:：]?\s*([0-9.\-]+)",
            "turnover_rate": r"换手率[:：]?\s*([0-9.\-]+)%",
            "volume_ratio": r"量比[:：]?\s*([0-9.\-]+)",
            "volume": r"成交量[:：]?\s*([0-9.\-]+)万",
            "amount": r"成交额[:：]?\s*([0-9.\-]+)亿",
        }
        for k, p in pairs.items():
            m = re.search(p, panel_text)
            if m:
                result[k] = parse_float(m.group(1))

    return result


def panel_text_to_lines(panel_text):
    if not panel_text:
        return []

    arr = [x.strip() for x in panel_text.splitlines() if x.strip()]
    if not arr:
        return []

    pairs = []
    i = 0
    while i < len(arr):
        if i + 1 < len(arr):
            pairs.append(f"{arr[i]}: {arr[i + 1]}")
            i += 2
        else:
            pairs.append(arr[i])
            i += 1

    lines = []
    for j in range(0, len(pairs), 4):
        lines.append("\t".join(pairs[j:j + 4]))
    return lines


