def is_valid_basic_info(info):
    if not info:
        return False
    if info.get("close") is None:
        return False

    core_count = 0
    for k in ["open", "prev_close", "high", "low"]:
        if info.get(k) is not None:
            core_count += 1

    return core_count >= 2


