def getStockAutoOnce(stockID: str, headless: bool, max_retry=2):
    jiaoyisuo = detect_market(stockID)
    today_date = today_str_dash()

    final_stock_name = None
    final_log_path = None

    for attempt in range(1, max_retry + 1):
        driver = None
        mode_name = "无头" if headless else "有头"

        try:
            write_run_status(f"{stockID} [{mode_name}] 第{attempt}次开始创建浏览器")
            driver = create_driver(headless=headless)
            write_run_status(f"{stockID} [{mode_name}] 第{attempt}次浏览器创建完成")

            if jiaoyisuo == 0:
                url = f"https://quote.eastmoney.com/concept/sz{stockID}.html"
            else:
                url = f"https://quote.eastmoney.com/concept/sh{stockID}.html"

            write_run_status(f"{stockID} [{mode_name}] 第{attempt}次准备打开网页: {url}")

            try:
                driver.get(url)
            except (TimeoutException, WebDriverException) as e:
                write_run_status(
                    f"{stockID} [{mode_name}] 第{attempt}次打开网页超时/异常，尝试继续解析页面: {type(e).__name__}: {e}"
                )

            wait_body(driver, 20)
            time.sleep(4)
            remove_masks(driver)

            stockName = safe_filename(get_stock_name(driver, stockID))
            log_path = os.path.join(OUTPUT_DIR, f"{stockName}.log")
            final_stock_name = stockName
            final_log_path = log_path

            block_status = today_block_status(log_path, today_date)
            if block_status == "valid":
                write_run_status(f"{stockID} {stockName} 今日有效数据已存在log，本次不追加写入。")
                return stockName, log_path, False, "today_already_exists"
            elif block_status == "invalid":
                removed = remove_today_blocks(log_path, today_date)
                write_run_status(f"{stockID} {stockName} 检测到今日残缺log块，已清理 {removed} 个，准备重抓。")

            ready_ok, basic_info = wait_basic_info_ready(driver, timeout=35)
            if not ready_ok:
                save_debug(driver, stockID, f"{mode_name}_basic_not_ready_attempt{attempt}")
                raise Exception(f"基本行情等待超时，最后抓取结果: {basic_info}")

            block = BlockCollector(echo=True)
            block.writeln(f"Date: {today_date}")
            block.writeln(f"股票数据： {stockName} {stockID} {today_str_compact()}")

            close_text, pct_text, panel_lines, basic_info = extract_basic_info_bundle(driver)
            block.writeln(close_text if close_text else "-")
            block.writeln(pct_text if pct_text else "-")

            if panel_lines:
                for line in panel_lines:
                    block.writeln(line)
            else:
                block.writeln("未找到基本行情区域")

            chip_tab_ok = click_with_retry(
                driver,
                [
                    "/html/body/div[1]/div/div[5]/div[1]/div/div[1]/ul/li[4]",
                    "//li[contains(.,'筹码')]",
                    "//span[contains(.,'筹码')]",
                    "//a[contains(.,'筹码')]",
                ],
            )

            if not chip_tab_ok:
                block.writeln("未找到筹码tab")
                save_debug(driver, stockID, f"{mode_name}_chip_tab_fail")
            else:
                time.sleep(2)
                remove_masks(driver)

                chip_dist_ok = click_with_retry(
                    driver,
                    [
                        "/html/body/div[1]/div/div[5]/div[1]/div/div[1]/div/a[1]",
                        "//a[contains(.,'筹码分布')]",
                        "//span[contains(.,'筹码分布')]",
                    ],
                )

                if not chip_dist_ok:
                    block.writeln("未找到筹码分布按钮")
                    save_debug(driver, stockID, f"{mode_name}_chip_dist_btn_fail")
                else:
                    time.sleep(4)
                    remove_masks(driver)

                    chip_text = extract_chip_distribution_strict(driver)
                    if chip_text:
                        block.writeln(f"筹码分布：{chip_text}")
                    else:
                        block.writeln("未找到筹码分布元素")
                        save_debug(driver, stockID, f"{mode_name}_chip_text_fail")

            kline_ok, ma_data, kline_lines = get_kline_and_ma(jiaoyisuo, stockID, max_retry=4, timeout=20)
            if not kline_ok or not is_valid_ma_data(ma_data):
                raise Exception("K线/均线抓取无效")

            block.writeln("")
            for line in kline_lines:
                block.writeln(line)

            append_block_text(log_path, block.get_text())
            return stockName, log_path, True, "success"

        except Exception as e:
            write_run_status(f"{stockID} [{mode_name}] 第{attempt}次抓取失败: {type(e).__name__}: {e}")
            try:
                if driver:
                    save_debug(driver, stockID, f"{'headless' if headless else 'headed'}_attempt{attempt}_fail")
            except:
                pass

        finally:
            try:
                if driver:
                    driver.quit()
            except:
                pass

        time.sleep(3)

    return final_stock_name, final_log_path, False, "failed"


